/// WGSL world-dimension constants generated by build.rs from `src/world_dims.rs`.
/// Prepended to every shader so the GPU and CPU agree on world size with a
/// single source of truth.
const WORLD_CONSTS_WGSL: &str = include_str!(concat!(env!("OUT_DIR"), "/world_consts.wgsl"));

/// Shared render-shader prelude (Camera uniform + tiny helpers). Prepended
/// after the world consts to raymarch/beam/taa so those three carry one
/// definition instead of a hand-maintained copy each. NOT used by physics/blit.
const COMMON_WGSL: &str = include_str!("../shaders/common.wgsl");

/// The shared in-brick DDA (`resolve_brick`) used by both the RT render path
/// and the accel-probe test, and the RT occlusion prelude that binds the world
/// acceleration structure. Only assembled into the RT shader variant.
const RT_VOXEL_QUERY_WGSL: &str = include_str!("../shaders/rt_voxel_query.wgsl");
const RT_SHADOW_WGSL: &str = include_str!("../shaders/rt_shadow.wgsl");
const RT_GI_WGSL: &str = include_str!("../shaders/rt_gi.wgsl");
const GI_PROBES_WGSL: &str = include_str!("../shaders/gi_probes.wgsl");
/// Probe-update amortization factor: 1/GI_PROBE_UPDATE_DIV of the probes are
/// re-gathered each frame (strided by the camera's gi_round). MUST match the
/// `GI_UPDATE_DIV` override default in gi_probes.wgsl.
const GI_PROBE_UPDATE_DIV: u32 = 8;
/// Probe gather-direction epochs: each probe cycles GI_PROBE_DIR_EPOCHS fixed
/// direction subsets (spherical Fibonacci), one per update round, so a static
/// scene converges to a periodic constant instead of random-walking. The
/// camera's gi_round counts frames mod DIV*EPOCHS: `% DIV` selects the probe
/// slice, `/ DIV` the epoch. MUST match `GI_DIR_EPOCHS` in gi_probes.wgsl.
const GI_PROBE_DIR_EPOCHS: u32 = 8;
const RT_PRIMARY_WGSL: &str = include_str!("../shaders/rt_primary.wgsl");

/// The per-voxel light field update pass (docs/VOXEL_LIGHTING_PLAN.md).
/// Concatenated LAST in both variants because it calls `shadow_occluded`,
/// whose definition is the RT prelude in one variant and the software
/// dispatcher appended after the render body in the other.
const VOXLIGHT_UPDATE_WGSL: &str = include_str!("../shaders/voxlight_update.wgsl");

/// Storage buffers the render layout binds in one compute stage. Named because
/// it is requested at device creation in two places AND must cover what
/// `create_compute_bgl` declares; a mismatch fails only at bind-group-layout
/// creation, deep inside GPU test output, so the two must not drift.
///
/// Group 0 declares 14 of them: the world pyramid, the deferred-transparent
/// records, the sprite atlas and the light field's four. The RT variant binds
/// group 1 in the SAME stage (three more), so its storage buffers count against
/// this limit too.
pub(crate) const COMPUTE_STORAGE_BUFFERS: u32 = 17;

/// Light-field update amortization: 1/VOXLIGHT_UPDATE_DIV of the live blocks
/// are re-gathered per frame, so the resident field refreshes every
/// VOXLIGHT_UPDATE_DIV frames. Mirrors the probe grid's cadence.
pub(crate) const VOXLIGHT_UPDATE_DIV: u32 = 8;

/// Sun-disc direction epochs the update pass cycles through, mirroring
/// `VL_SUN_EPOCHS` in shaders/voxlight_update.wgsl. One definition on each side
/// of the language boundary is one too many, but the shader constant cannot be
/// imported, so this is the Rust name for it and the tests that reason about the
/// cycle use this rather than spelling 8 again.
pub(crate) const VOXLIGHT_SUN_EPOCHS: u32 = 8;

/// Extra amortization applied to lit shell FURTHER than
/// `World::LIGHT_NEAR_RADIUS` from the camera, on top of `VOXLIGHT_UPDATE_DIV`.
///
/// The update pass used to walk the entire resident shell every 8 frames with no
/// idea where the camera was, and on the shipped benchmark that made it the
/// LARGEST single GPU pass in the frame - 0.95 to 2.09 ms, 18-32% of the GPU
/// time, ahead of the raymarch itself on four of the six segments. It is also the
/// one pass in the frame whose cost has nothing to do with what is on screen: a
/// streamed world binds ~60,000 blocks and a camera can see a small fraction of
/// them.
///
/// 8 makes a distant block's refresh period 64 frames instead of 8. That is a
/// REFRESH RATE, not a storage or shading change - the record stays allocated,
/// stays valid and is read exactly as before, so nothing renders differently
/// once converged. What it costs is tracking latency for a moving sun and for
/// freshly streamed geometry, both of which are bounded and both of which are
/// worst exactly where fog has already taken over. See `LightField::near_count`.
pub(crate) const VOXLIGHT_FAR_DIV: u32 = 8;

/// Sun rotation, in radians, that buys ONE sweep round.
///
/// The sweep exists to track the sun and nothing else, so this is the only
/// honest unit for its cadence. The value reproduces the schedule this pass has
/// always had at 60 fps and the shipped sun speed, so the LOOK is unchanged; what
/// changes is that the schedule no longer depends on the FRAME RATE. At 400 fps
/// it issues a round on one frame in seven instead of on every one, and with the
/// sun frozen it issues none at all.
///
/// The value is one frame's worth of real sun motion at 60 Hz, and the factor
/// nobody expects is in it. `sun_dir_at(t) = normalize(cos a, sin a, 0.30)` with
/// `a = 0.025 t`, so the NORMALIZED direction does not turn at 0.025 rad/s: it
/// traces a cone, a circle of radius `1 / sqrt(1 + 0.30^2)` = 0.95783 on the unit
/// sphere, and sweeps `0.025 * 0.95783` rad/s of real angle. Using the naive
/// 0.025 here would over-charge by 4.3% and quietly refresh slightly less often
/// than the old cadence did.
///
/// Measured justification for not going slower than this:
/// `voxlight_sun_lag_error` on the demo world reports, per sun lag, the fraction
/// of records whose stored byte moves and by how much -
///
///     lag 0.133 s (a near period): 0.75% change, mean 0.21/255, p99 0
///     lag 1.067 s (a far period):  1.98% change, mean 0.59/255, p99 31
///     lag 4.267 s:                 3.15% change, mean 2.63/255, p99 95
///
/// so the shipped periods sit where the p99 error is still inside a byte or two
/// and the tail only starts moving well past them. Keeping them exactly as they
/// were means the LOOK is unchanged by this rework and only the frame-rate
/// coupling is removed.
pub(crate) const VOXLIGHT_SUN_RAD_PER_ROUND: f32 = 0.025 * 0.957826 / 60.0;

/// Sweep rounds per SECOND while geometry is still settling, when the sun alone
/// would ask for fewer.
///
/// A brick edit owes one complete sweep (`VOXLIGHT_UPDATE_DIV *
/// VOXLIGHT_FAR_DIV` = 64 rounds) because a placed block's shadow can land
/// anywhere along the sun ray and nothing local can know where. 64 rounds per
/// second is that sweep finishing in one second, which is the same worst-case
/// latency the far group already had.
pub(crate) const VOXLIGHT_DIRTY_SWEEP_HZ: f32 = 64.0;

/// Ceiling on banked sweep rounds.
///
/// A hitch (a chunk-generation stall, an alt-tab) must not be repaid as a burst
/// of dispatches on the frame after it: the field would catch up in one frame
/// what it should have spread over sixty, which is a spike exactly where the
/// frame is already late. One round of slack absorbs ordinary frame-time jitter;
/// anything past that is simply forgiven, and the sun is tracked a few
/// milliseconds behind for one sweep.
const VOXLIGHT_ROUND_CREDIT_MAX: f32 = 2.0;

/// WHEN the light field's periodic sweep is allowed to run, and how often.
///
/// This is the whole of the "do no work when nothing changed" gate, in one place
/// so the renderer and the live-session harness cannot measure different
/// policies.
///
/// A record's value is a function of (geometry, sun direction, light set), so
/// re-gathering it when none of the three moved writes bytes that are already
/// there - measured on the demo world, 99.25% of records come back BIT-IDENTICAL
/// across a whole near-sweep period of sun motion (`voxlight_sun_lag_error`).
/// The sweep therefore accrues at a rate set by how fast the sun is actually
/// turning, plus a floor while geometry is still settling, and a round is issued
/// only when a whole one has accrued. Consequences, in order of importance:
///
///  - a frozen sun over unchanged geometry issues NOTHING, for ever;
///  - the cost per SECOND is fixed, so a session running at 400 fps pays the
///    same per second as one at 60 and about a sixth as much per FRAME. The old
///    frame-counter cadence refreshed the field six times more often at 400 fps
///    than the design ever asked for, for no benefit at all;
///  - a sun sped up, slowed or scrubbed is tracked at the rate it needs, because
///    the accrual measures the real angle between two sun directions rather than
///    assuming the shipped rate.
///
/// Everything that CANNOT wait for a sweep - a block with no record, an edited
/// brick, its neighbours - goes on `LightField::urgent` instead and is dispatched
/// on the next frame whatever this says.
#[derive(Default)]
pub(crate) struct VoxLightSchedule {
    /// Sweep rounds owed, fractional.
    credit: f32,
    /// The two clocks the accrual is measured against. `None` means no history,
    /// which is treated as "everything is due".
    prev_sun_time: Option<f32>,
    prev_time: Option<f32>,
    /// Sweep rounds still owed because GEOMETRY changed rather than because the
    /// sun moved. The urgent list covers the edited bricks and their neighbours
    /// exactly, but a placed block also moves a SHADOW, and that shadow can land
    /// anywhere along the sun ray - nothing local can know where, so a geometry
    /// change owes one complete pass over the shell.
    dirty_rounds: u32,
}

impl VoxLightSchedule {
    /// Geometry changed somewhere: owe one complete sweep.
    pub(crate) fn mark_dirty(&mut self) {
        self.dirty_rounds = VOXLIGHT_UPDATE_DIV * VOXLIGHT_FAR_DIV;
    }

    /// Bank this frame's share of a round from the two clocks.
    pub(crate) fn accrue(&mut self, time: f32, sun_time: f32) {
        let (prev_sun, prev_t) = match (self.prev_sun_time, self.prev_time) {
            (Some(s), Some(t)) => (s, t),
            _ => {
                self.prev_sun_time = Some(sun_time);
                self.prev_time = Some(time);
                self.credit = VOXLIGHT_ROUND_CREDIT_MAX;
                return;
            }
        };
        self.prev_sun_time = Some(sun_time);
        self.prev_time = Some(time);
        // A real ANGLE between the two sun directions, not a difference of
        // `sun_time`: a sun that is paused, scrubbed or run backwards is then
        // accounted correctly instead of by assuming the shipped rate.
        //
        // From the CHORD, `theta = 2 asin(|a - b| / 2)`, and NOT from
        // `acos(dot(a, b))`. The two are the same angle and only one of them is
        // usable here: `dot` of a unit vector with itself comes back as
        // 0.99999994 rather than 1.0, and `acos` has infinite slope there, so a
        // FROZEN sun measured that way reads as 3.4e-4 rad of motion per frame -
        // 82% of a round - and the gate never closes. Measured: the frozen-sun
        // case ran 599 sweeps in 600 frames. `asin` near zero is exact.
        let (a, b) = (crate::camera::sun_dir_at(prev_sun), crate::camera::sun_dir_at(sun_time));
        let d_sun = 2.0 * ((a - b).length() * 0.5).clamp(-1.0, 1.0).asin();
        let sun_rounds = d_sun / VOXLIGHT_SUN_RAD_PER_ROUND;
        // The two rates are a MAX, not a sum: they are two lower bounds on how
        // fast the same sweep has to run, not two independent pieces of work.
        let dirty_rounds = if self.dirty_rounds > 0 {
            (time - prev_t).max(0.0) * VOXLIGHT_DIRTY_SWEEP_HZ
        } else {
            0.0
        };
        self.credit = (self.credit + sun_rounds.max(dirty_rounds)).min(VOXLIGHT_ROUND_CREDIT_MAX);
    }

    /// Issue a sweep round if a whole one is owed.
    pub(crate) fn take_round(&mut self) -> bool {
        if self.credit < 1.0 {
            return false;
        }
        self.credit -= 1.0;
        self.dirty_rounds = self.dirty_rounds.saturating_sub(1);
        true
    }
}

/// Update rounds a headless harness must run before the light field is at
/// steady state, i.e. what a still or a timing sample has to see, or it is
/// judging the amortization schedule rather than the lighting.
///
/// The update pass visits a block once every `VOXLIGHT_UPDATE_DIV` rounds and
/// folds an exponential average of the sun disc into it, so this is 24 visits
/// per block: well past that fold's settling time on a static sun. It used to
/// be sized by the (slower, now deleted) reflection pass, which is why the
/// number is unchanged while the reasoning behind it is not.
pub(crate) const VOXLIGHT_CONVERGE_ROUNDS: u32 = VOXLIGHT_UPDATE_DIV * 24;

/// Software dispatchers injected into the non-RT variant so the render body's
/// `shadow_occluded(...)` and `indirect_light(...)` calls resolve to the
/// pre-RT behaviour: occlusion forwards to the DDA `trace_any`, and there is no
/// one-bounce indirect (returns 0, the ambient-only look).
const SHADOW_SW_WGSL: &str = concat!(
    "fn shadow_occluded(o: vec3<f32>, d: vec3<f32>, m: f32) -> bool { return trace_any(o, d, m); }\n",
    "fn indirect_light(p: vec3<f32>, n: vec3<f32>, seed: f32, px: vec2<i32>, t: f32, v: vec3<f32>) -> vec3<f32> { return vec3<f32>(0.0); }\n",
    "fn trace_secondary(o: vec3<f32>, d: vec3<f32>, cap: f32) -> Hit { return trace_no_water(o, d, cap); }\n",
    "fn rt_primary_or_none(origin: vec3<f32>, dir: vec3<f32>, skip_transparent: bool, done: ptr<function, bool>) -> Hit { *done = false; var h: Hit; h.hit = false; h.mat = 0u; h.normal = vec3<f32>(0.0); h.voxel = vec3<i32>(0); h.last_axis = -1; h.t_hit = 0.0; h.tint = vec3<f32>(1.0); return h; }\n",
);

/// Full raymarch shader source: world consts + common prelude + the sprite
/// atlas consts generated from `src/sprites.rs` + the shader body. The ONE
/// assembly point shared by the pipeline, the naga validation test and the
/// GPU test harness, so what is validated/tested is what runs.
///
/// `rt` selects the hardware-ray-tracing variant: it enables `wgpu_ray_query`,
/// binds the world acceleration structure and routes `shadow_occluded` through
/// the RT core. The software variant is byte-identical to the pre-RT shader plus
/// the tiny forwarding dispatcher, so a non-RT GPU renders exactly as before.
pub(crate) fn raymarch_source_variant(rt: bool) -> String {
    if rt {
        format!(
            "enable wgpu_ray_query;\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}",
            WORLD_CONSTS_WGSL,
            COMMON_WGSL,
            crate::sprites::wgsl_consts(),
            RT_VOXEL_QUERY_WGSL,
            RT_SHADOW_WGSL,
            RT_GI_WGSL,
            GI_PROBES_WGSL,
            RT_PRIMARY_WGSL,
            include_str!("../shaders/raymarch.wgsl"),
            VOXLIGHT_UPDATE_WGSL,
        )
    } else {
        format!(
            "{}\n{}\n{}\n{}\n{}\n{}",
            WORLD_CONSTS_WGSL,
            COMMON_WGSL,
            crate::sprites::wgsl_consts(),
            include_str!("../shaders/raymarch.wgsl"),
            SHADOW_SW_WGSL,
            VOXLIGHT_UPDATE_WGSL,
        )
    }
}

/// Software (non-RT) raymarch source. Kept as the name the existing pipeline,
/// validation test and GPU harness call.
pub(crate) fn raymarch_source() -> String {
    raymarch_source_variant(false)
}

/// Pack a Vec<u8> into Vec<u32> for storage-buffer upload (WGSL storage
/// buffers can't directly index u8 arrays; reading byte b of word w via
/// `(packed[w] >> ((b & 3) * 8)) & 0xFF` is the canonical pattern).
fn pack_u8_to_u32(src: &[u8]) -> Vec<u32> {
    let n_words = (src.len() + 3) / 4;
    let mut out = vec![0u32; n_words];
    for (i, &b) in src.iter().enumerate() {
        let w = i >> 2;
        let bit = (i & 3) * 8;
        out[w] |= (b as u32) << bit;
    }
    out
}

/// Coalesce a SORTED, DEDUPED slice of element indices into runs and invoke
/// `f(start, end_inclusive)` once per run. Turns thousands of tiny DMAs into a
/// handful of multi-KB writes.
///
/// `gap` is how many MISSING indices may be swept into a run rather than split
/// it. A `write_buffer` costs a staging-belt allocation, a memcpy and a recorded
/// copy whichever way the bytes go, so past some element count it is cheaper to
/// re-send untouched elements than to issue a second write. The caller states
/// that tolerance because only the caller knows the element size AND whether
/// re-sending an untouched element is even legal: it is for a table (the value
/// is simply written again), and it is NOT for a pool of blocks where the gap
/// belongs to a different, live tenant.
fn upload_spans(sorted: &[u32], gap: u32, mut f: impl FnMut(u32, u32)) {
    let mut i = 0usize;
    while i < sorted.len() {
        let start = sorted[i];
        let mut end = start;
        let mut j = i + 1;
        while j < sorted.len() && sorted[j] <= end.saturating_add(gap).saturating_add(1) {
            end = sorted[j];
            j += 1;
        }
        f(start, end);
        i = j;
    }
}

/// Upload the given packed-u32 word indices (sorted, deduped) of a byte table
/// (1 byte per element, packed 4 per word) by re-packing each contiguous word
/// run from `bytes` and writing it at the matching word offset.
fn upload_packed_word_spans(
    words: &[u32],
    bytes: &[u8],
    queue: &wgpu::Queue,
    buf: &wgpu::Buffer,
) {
    // gap 0: a packed-byte table re-packs each run from `bytes`, so widening a
    // run costs a re-pack as well as a re-send, and these lists are already dense.
    upload_spans(words, 0, |w_start, w_end| {
        let b0 = (w_start as usize) * 4;
        let b1 = (((w_end as usize) + 1) * 4).min(bytes.len());
        let packed = pack_u8_to_u32(&bytes[b0..b1]);
        queue.write_buffer(buf, w_start as u64 * 4, bytemuck::cast_slice(&packed));
    });
}

/// Project element indices `src` to their packed-u32 word indices (deduped via
/// `scratch`) and re-pack + upload only those words of the byte `table`. Shared
/// by the brick-uniform and tile-uniform incremental uploads.
fn upload_words_for(
    scratch: &mut Vec<u32>, src: &[u32], table: &[u8], queue: &wgpu::Queue, buf: &wgpu::Buffer,
) {
    scratch.clear();
    for &x in src {
        let w = x >> 2;
        if scratch.last() != Some(&w) { scratch.push(w); }
    }
    upload_packed_word_spans(scratch, table, queue, buf);
}

/// Project a set of tile indices up to their parent chunks (via `scratch`, which
/// is sorted+deduped) and DMA the touched chunk_mask runs. Does NOT refresh L4 â€”
/// the caller decides that.
fn upload_chunks_for_tiles(
    scratch: &mut Vec<u32>, tiles: &[u32], chunk_mask: &[u64], queue: &wgpu::Queue, buf: &wgpu::Buffer,
) {
    scratch.clear();
    for &t in tiles {
        let tx = t % WORLD_TILES_X;
        let ty = (t / WORLD_TILES_X) % WORLD_TILES_Y;
        let tz = t / (WORLD_TILES_X * WORLD_TILES_Y);
        scratch.push(chunk_idx(tx / 4, ty / 4, tz / 4));
    }
    scratch.sort_unstable();
    scratch.dedup();
    upload_spans(scratch, 0, |s, e| {
        let slice = &chunk_mask[s as usize..=e as usize];
        queue.write_buffer(buf, s as u64 * 8, bytemuck::cast_slice(slice));
    });
}

