    // The world-space probe cache must actually LIGHT the scene: after the update
    // pass converges the probes, indirect must add real, bounded light (brighter
    // than GI-off, not zero, not blown out, no NaN). Proves the SH gather/project/
    // sample chain end-to-end on the GPU - CPU tests can't see this.
    #[test]
    fn probe_gi_lights_the_scene() {
        let Some((device, queue, _gpu)) = rt_headless_device() else {
            eprintln!("probe_gi_lights_the_scene: no RT adapter, skipping");
            return;
        };
        let (device, queue) = (&device, &queue);
        let mut world = World::new();
        world.fill_demo_terrain();
        let (_wa, leaf_anchor, leaf_ground) = find_scene_anchors(&world);
        // Under-canopy view: plenty of shadowed geometry that indirect should lift.
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(clamp_anchor(leaf_anchor.x), leaf_ground as f32 + 6.0, clamp_anchor(leaf_anchor.y) - 18.0);
        cam.pitch = -0.15;

        let (w, h) = (320u32, 200u32);
        let wo = world.world_origin_voxel();
        let cu = CameraUniform::from_camera(&cam, w, h, 30.0, 30.0, wo, [0.0, 0.0], 0.0);
        let camera_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("camera"), contents: bytemuck::bytes_of(&cu),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let bricks_buf = storage(device, "bricks", bytemuck::cast_slice(&world.bricks));
        let tile_mask_buf = storage(device, "tile_mask", bytemuck::cast_slice(&world.tile_mask));
        let chunk_mask_buf = storage(device, "chunk_mask", bytemuck::cast_slice(&world.chunk_mask));
        let l4_mask_buf = storage(device, "l4_mask", bytemuck::cast_slice(&world.l4_mask));
        let brick_uniform_buf = storage(device, "bu", bytemuck::cast_slice(&pack_u8_to_u32(&world.brick_uniform)));
        let tile_uniform_buf = storage(device, "tu", bytemuck::cast_slice(&pack_u8_to_u32(&world.tile_uniform)));
        let palette = default_palette();
        let palette_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("palette"), contents: bytemuck::cast_slice(&palette),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let words = (((w + 7) / 8 * ((h + 7) / 8)) as usize + 31) / 32;
        let tile_dirty_buf = storage(device, "tile_dirty", bytemuck::cast_slice(&vec![u32::MAX; words]));
        let players_buf = storage(device, "players", &vec![0u8; 16 + MAX_REMOTE_PLAYERS * 16]);
        let (out_tex, output_view) = create_hdr_texture(device, w, h);
        let (_btex, beam_view) = create_beam_texture(device, w, h);
        let (_ctex, cloud_sampled_view, _cloud_storage_view) = create_cloud_texture(device, w, h);
        let cloud_sampler = device.create_sampler(&wgpu::SamplerDescriptor { label: None, mag_filter: wgpu::FilterMode::Linear, min_filter: wgpu::FilterMode::Linear, ..Default::default() });
        let (_ltex2, light_out_view) = create_lighting_texture(device, w, h);
        let transp_buf = create_transp_buf(device, w, h);
        let sprites_buf = storage(device, "sprites", bytemuck::cast_slice(&crate::sprites::encoded()));
        let (_dtex, depth_view) = create_depth_texture(device, w, h);
        let (_gtex, geom_view) = create_hdr_texture(device, w, h);
        let (_ddtex, dummy_depth_view) = create_depth_texture(device, 1, 1);
        let bgl = create_compute_bgl(device);
        let vl_bufs = VoxLightBuffers::new(device);
        let bg = make_compute_bg(
            device, &bgl, &camera_buf, &bricks_buf, &tile_mask_buf, &chunk_mask_buf,
            &palette_buf, &output_view, &beam_view, &tile_dirty_buf, &players_buf,
            &brick_uniform_buf, &tile_uniform_buf, &l4_mask_buf,
            &cloud_sampled_view, &cloud_sampler, &light_out_view, &transp_buf,
            &sprites_buf, &dummy_depth_view, &geom_view, &depth_view, &vl_bufs,
        );
        let accel = crate::accel::build_world_accel(device, queue, &world);
        let rt_bgl = create_rt_bgl(device);
        let (_gi_i, gi_iv) = create_lighting_texture(device, w, h);
        let (_gi_o, gi_ov) = create_lighting_texture(device, w, h);
        let probe_buf = create_probe_buf(device);
        let rt_bg = make_rt_bg(device, &rt_bgl, &accel, &gi_iv, &gi_ov, &probe_buf);
        let rt_module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: None, source: wgpu::ShaderSource::Wgsl(raymarch_source_variant(true).into()),
        });
        let rt_pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: None, bind_group_layouts: &[Some(&bgl), Some(&rt_bgl)], immediate_size: 0,
        });
        let mk = |entry: &'static str, consts: &[(&'static str, f64)]| device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: None, layout: Some(&rt_pl), module: &rt_module, entry_point: Some(entry),
            compilation_options: wgpu::PipelineCompilationOptions { constants: consts, ..Default::default() }, cache: None,
        });
        // RT primary on both so the ONLY difference is the indirect term.
        let off = mk("cs_main", &[("GI_ENABLE", 0.0), ("RT_PRIMARY", 1.0)]);
        let on = mk("cs_main", &[("GI_ENABLE", 1.0), ("RT_PRIMARY", 1.0), ("GI_PROBE_MODE", 1.0)]);
        // DIV=1: this test converges by dispatching the update repeatedly, so it
        // must touch every probe each pass (no amortization striding).
        let update = mk("cs_gi_probe_update", &[("GI_ENABLE", 1.0), ("RT_PRIMARY", 1.0), ("GI_PROBE_MODE", 1.0), ("GI_UPDATE_DIV", 1.0)]);

        let bpr = w * 8; // rgba16float texels
        let render = |main: &wgpu::ComputePipeline, converge: u32| -> Vec<u8> {
            let mut enc = device.create_command_encoder(&Default::default());
            // Converge the probes (each pass = one frame of temporal accumulation).
            for _ in 0..converge {
                let mut cp = enc.begin_compute_pass(&Default::default());
                cp.set_pipeline(&update);
                cp.set_bind_group(0, &bg, &[]);
                cp.set_bind_group(1, &rt_bg, &[]);
                cp.dispatch_workgroups((crate::voxel::PROBE_TOTAL + 63) / 64, 1, 1);
            }
            {
                let mut cp = enc.begin_compute_pass(&Default::default());
                cp.set_pipeline(main);
                cp.set_bind_group(0, &bg, &[]);
                cp.set_bind_group(1, &rt_bg, &[]);
                cp.dispatch_workgroups((w + 7) / 8, (h + 7) / 8, 1);
            }
            let readback = device.create_buffer(&wgpu::BufferDescriptor {
                label: None, size: (bpr * h) as u64,
                usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ, mapped_at_creation: false,
            });
            enc.copy_texture_to_buffer(
                wgpu::TexelCopyTextureInfo { texture: &out_tex, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
                wgpu::TexelCopyBufferInfo { buffer: &readback, layout: wgpu::TexelCopyBufferLayout { offset: 0, bytes_per_row: Some(bpr), rows_per_image: Some(h) } },
                wgpu::Extent3d { width: w, height: h, depth_or_array_layers: 1 },
            );
            queue.submit(std::iter::once(enc.finish()));
            let slice = readback.slice(..);
            slice.map_async(wgpu::MapMode::Read, |_| {});
            device.poll(wgpu::PollType::wait_indefinitely()).unwrap();
            let raw = slice.get_mapped_range().unwrap().to_vec();
            // Fold rgba16float texels to the rgba8 layout the luma math uses.
            let half_to_u8 = |bits: u16| -> u8 {
                let exp = ((bits >> 10) & 0x1F) as i32;
                let man = (bits & 0x3FF) as f32;
                let mag = if exp == 0 {
                    man / 1024.0 * (-14f32).exp2()
                } else {
                    (1.0 + man / 1024.0) * ((exp - 15) as f32).exp2()
                };
                let v = if bits & 0x8000 != 0 { -mag } else { mag };
                (v.clamp(0.0, 1.0) * 255.0).round() as u8
            };
            let mut out = vec![0u8; (w * h * 4) as usize];
            for i in 0..(w * h) as usize {
                for c in 0..4 {
                    let bits = u16::from_le_bytes([raw[i * 8 + c * 2], raw[i * 8 + c * 2 + 1]]);
                    out[i * 4 + c] = half_to_u8(bits);
                }
            }
            out
        };

        let a = render(&off, 0);          // GI off
        let b = render(&on, 80);          // probe GI, converged over 80 update passes

        let n = (w * h) as usize;
        let (mut sum_a, mut sum_b, mut max_b, mut brighter) = (0.0f64, 0.0f64, 0u32, 0usize);
        for i in 0..n {
            let la = (a[i * 4] as u32 + a[i * 4 + 1] as u32 + a[i * 4 + 2] as u32) / 3;
            let lb = (b[i * 4] as u32 + b[i * 4 + 1] as u32 + b[i * 4 + 2] as u32) / 3;
            sum_a += la as f64; sum_b += lb as f64; max_b = max_b.max(lb);
            if lb > la + 3 { brighter += 1; }
        }
        let (mean_a, mean_b) = (sum_a / n as f64, sum_b / n as f64);
        let bright_frac = brighter as f64 / n as f64;
        eprintln!("probe_gi_lights_the_scene: mean_luma off={mean_a:.2} probeGI={mean_b:.2} brighter_frac={bright_frac:.3} max_b={max_b}");
        // Indirect only ADDS light: the GI frame must be brighter overall.
        assert!(mean_b > mean_a + 0.5, "probe GI added no measurable light (off {mean_a:.2} vs GI {mean_b:.2})");
        // GI must be spatially present, not a flat tiny offset on a few pixels.
        assert!(bright_frac > 0.15, "probe GI lit too few pixels ({bright_frac:.3}); gather/sample likely broken");
        // ...but bounded: no blow-out / NaN-to-255 everywhere, and not a 2x over-bright wash.
        assert!(max_b <= 255, "impossible luma");
        assert!(mean_b < mean_a * 2.2 + 20.0, "probe GI over-bright ({mean_b:.2} vs off {mean_a:.2}); SH scale wrong");
    }

    fn rt_ab_check(device: &wgpu::Device, queue: &wgpu::Queue, world: &World, cam: &Camera, label: &str, rt_consts: &[(&'static str, f64)], tol: f64) {
        let (w, h) = (320u32, 200u32);
        let wo = world.world_origin_voxel();
        let t = 30.0;
        let cu = CameraUniform::from_camera(cam, w, h, t, t, wo, [0.0, 0.0], 0.0);

        // ---- group-0 bindings (mirrors render_rgba_full) ----
        let camera_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("camera"),
            contents: bytemuck::bytes_of(&cu),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let bricks_buf = storage(device, "bricks", bytemuck::cast_slice(&world.bricks));
        let tile_mask_buf = storage(device, "tile_mask", bytemuck::cast_slice(&world.tile_mask));
        let chunk_mask_buf = storage(device, "chunk_mask", bytemuck::cast_slice(&world.chunk_mask));
        let l4_mask_buf = storage(device, "l4_mask", bytemuck::cast_slice(&world.l4_mask));
        let brick_uniform_buf = storage(device, "bu", bytemuck::cast_slice(&pack_u8_to_u32(&world.brick_uniform)));
        let tile_uniform_buf = storage(device, "tu", bytemuck::cast_slice(&pack_u8_to_u32(&world.tile_uniform)));
        let palette = default_palette();
        let palette_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("palette"),
            contents: bytemuck::cast_slice(&palette),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let tiles_w = (w + 7) / 8;
        let tiles_h = (h + 7) / 8;
        let words = ((tiles_w * tiles_h) as usize + 31) / 32;
        let tile_dirty_buf = storage(device, "tile_dirty", bytemuck::cast_slice(&vec![u32::MAX; words]));
        let players_buf = storage(device, "players", &vec![0u8; 16 + MAX_REMOTE_PLAYERS * 16]);
        let (out_tex, output_view) = create_hdr_texture(device, w, h);
        let (_btex, beam_view) = create_beam_texture(device, w, h);
        let (_ctex, cloud_sampled_view, _cloud_storage_view) = create_cloud_texture(device, w, h);
        let cloud_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("cloud samp"),
            mag_filter: wgpu::FilterMode::Linear,
            min_filter: wgpu::FilterMode::Linear,
            ..Default::default()
        });
        let (_ltex2, light_out_view) = create_lighting_texture(device, w, h);
        let transp_buf = create_transp_buf(device, w, h);
        let sprites_buf = storage(device, "sprites", bytemuck::cast_slice(&crate::sprites::encoded()));
        let (_dtex, depth_view) = create_depth_texture(device, w, h);
        let (_gtex, geom_view) = create_hdr_texture(device, w, h);
        let (_ddtex, dummy_depth_view) = create_depth_texture(device, 1, 1);
        let bgl = create_compute_bgl(device);
        let vl_bufs = VoxLightBuffers::new(device);
        let bg = make_compute_bg(
            device, &bgl, &camera_buf, &bricks_buf, &tile_mask_buf, &chunk_mask_buf,
            &palette_buf, &output_view, &beam_view, &tile_dirty_buf, &players_buf,
            &brick_uniform_buf, &tile_uniform_buf, &l4_mask_buf,
            &cloud_sampled_view, &cloud_sampler, &light_out_view, &transp_buf,
            &sprites_buf, &dummy_depth_view, &geom_view, &depth_view, &vl_bufs,
        );

        // ---- group-1 (RT) bindings, built from the live world ----
        let accel = crate::accel::build_world_accel(device, queue, &world);
        let rt_bgl = create_rt_bgl(device);
        let (_gi_i, gi_iv) = create_lighting_texture(device, w, h);
        let (_gi_o, gi_ov) = create_lighting_texture(device, w, h);
        let probe_buf = create_probe_buf(device);
        let rt_bg = make_rt_bg(device, &rt_bgl, &accel, &gi_iv, &gi_ov, &probe_buf);

        // ---- pipelines ----
        let sw_module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("sw raymarch"),
            source: wgpu::ShaderSource::Wgsl(raymarch_source().into()),
        });
        let sw_pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("sw pl"),
            bind_group_layouts: &[Some(&bgl)],
            immediate_size: 0,
        });
        let sw_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("sw cs_main"),
            layout: Some(&sw_pl),
            module: &sw_module,
            entry_point: Some("cs_main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let rt_module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("rt raymarch"),
            source: wgpu::ShaderSource::Wgsl(raymarch_source_variant(true).into()),
        });
        let rt_pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("rt pl"),
            bind_group_layouts: &[Some(&bgl), Some(&rt_bgl)],
            immediate_size: 0,
        });
        let rt_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("rt cs_main"),
            layout: Some(&rt_pl),
            module: &rt_module,
            entry_point: Some("cs_main"),
            compilation_options: wgpu::PipelineCompilationOptions {
                constants: rt_consts,
                ..Default::default()
            },
            cache: None,
        });

        // The output is HDR rgba16float now: read 8-byte texels and fold the
        // halves back to the u8 space the comparison math was written for.
        let bpr = w * 8;
        let half_to_u8 = |bits: u16| -> u8 {
            let exp = ((bits >> 10) & 0x1F) as i32;
            let man = (bits & 0x3FF) as f32;
            let mag = if exp == 0 {
                man / 1024.0 * (-14f32).exp2()
            } else {
                (1.0 + man / 1024.0) * ((exp - 15) as f32).exp2()
            };
            let v = if bits & 0x8000 != 0 { -mag } else { mag };
            (v.clamp(0.0, 1.0) * 255.0).round() as u8
        };
        let render = |pipeline: &wgpu::ComputePipeline, rt: bool| -> Vec<u8> {
            let readback = device.create_buffer(&wgpu::BufferDescriptor {
                label: Some("readback"),
                size: (bpr * h) as u64,
                usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
                mapped_at_creation: false,
            });
            let mut enc = device.create_command_encoder(&Default::default());
            {
                let mut cp = enc.begin_compute_pass(&Default::default());
                cp.set_pipeline(pipeline);
                cp.set_bind_group(0, &bg, &[]);
                if rt {
                    cp.set_bind_group(1, &rt_bg, &[]);
                }
                cp.dispatch_workgroups((w + 7) / 8, (h + 7) / 8, 1);
            }
            enc.copy_texture_to_buffer(
                wgpu::TexelCopyTextureInfo {
                    texture: &out_tex, mip_level: 0, origin: wgpu::Origin3d::ZERO,
                    aspect: wgpu::TextureAspect::All,
                },
                wgpu::TexelCopyBufferInfo {
                    buffer: &readback,
                    layout: wgpu::TexelCopyBufferLayout { offset: 0, bytes_per_row: Some(bpr), rows_per_image: Some(h) },
                },
                wgpu::Extent3d { width: w, height: h, depth_or_array_layers: 1 },
            );
            queue.submit(std::iter::once(enc.finish()));
            let slice = readback.slice(..);
            slice.map_async(wgpu::MapMode::Read, |_| {});
            device.poll(wgpu::PollType::wait_indefinitely()).unwrap();
            let raw = slice.get_mapped_range().unwrap().to_vec();
            let mut out = vec![0u8; (w * h * 4) as usize];
            for i in 0..(w * h) as usize {
                for c in 0..4 {
                    let bits = u16::from_le_bytes([raw[i * 8 + c * 2], raw[i * 8 + c * 2 + 1]]);
                    out[i * 4 + c] = half_to_u8(bits);
                }
            }
            out
        };

        let sw = render(&sw_pipeline, false);
        let rt = render(&rt_pipeline, true);

        // Compare RGB channels. Nearly all pixels must match; a small tail of
        // grazing shadow/AO edge pixels may differ by a little.
        let n = (w * h) as usize;
        let mut sum_abs = 0.0f64;
        let mut max_abs = 0u32;
        let mut big = 0usize;
        let mut sw_luma_min = 255u8;
        let mut sw_luma_max = 0u8;
        for i in 0..n {
            let l = ((sw[i * 4] as u32 + sw[i * 4 + 1] as u32 + sw[i * 4 + 2] as u32) / 3) as u8;
            sw_luma_min = sw_luma_min.min(l);
            sw_luma_max = sw_luma_max.max(l);
            for c in 0..3 {
                let d = (sw[i * 4 + c] as i32 - rt[i * 4 + c] as i32).unsigned_abs();
                sum_abs += d as f64;
                max_abs = max_abs.max(d);
                if d > 24 {
                    big += 1;
                }
            }
        }
        let mean_abs = sum_abs / (n as f64 * 3.0);
        eprintln!(
            "rt_shadows_match_software[{label}]: mean|dRGB|={mean_abs:.3} max={max_abs} big(>24)={big}/{} sw_luma[{sw_luma_min}..{sw_luma_max}]",
            n * 3
        );
        // The scene must actually have shading contrast (not a flat frame), else
        // the comparison proves nothing.
        assert!(sw_luma_max as i32 - sw_luma_min as i32 > 60, "[{label}] software frame has no contrast; A/B meaningless");
        assert!(mean_abs < tol, "[{label}] RT vs software frame differs too much: mean |dRGB| = {mean_abs:.3} (tol {tol})");
        assert!(big < n / 12, "[{label}] too many large-diff channels ({big}) between RT and software");
    }

    #[test]
    fn accel_signature_tracks_brick_set_not_content() {
        use crate::voxel::{MAT_AIR, MAT_STONE};
        let mut w = World::new();
        // Fill one brick (empty -> non-empty): the BLAS set changed.
        w.set_voxel(40, 60, 40, MAT_STONE);
        let sig1 = accel_signature(&w);
        // Content-only edit in the SAME, still-non-empty brick: BLAS unchanged,
        // so the signature must be identical (this is the rebuild we skip).
        w.set_voxel(41, 60, 40, MAT_STONE);
        assert_eq!(accel_signature(&w), sig1, "content-only edit must not change the accel signature");
        // A different empty brick becomes non-empty: signature must change.
        w.set_voxel(80, 60, 80, MAT_STONE);
        let sig2 = accel_signature(&w);
        assert_ne!(sig2, sig1, "a new non-empty brick must change the signature");
        // Emptying a brick (non-empty -> empty): signature must change.
        w.set_voxel(40, 60, 40, MAT_AIR);
        w.set_voxel(41, 60, 40, MAT_AIR);
        assert_ne!(accel_signature(&w), sig2, "emptying a brick must change the signature");
        // Window origin is part of the signature (streaming rebuilds the accel).
        let before = accel_signature(&w);
        w.world_origin_chunk = glam::IVec2::new(2, 3);
        assert_ne!(accel_signature(&w), before, "a window-origin shift must change the signature");
    }

    fn assert_sane(label: &str, min: f32, max: f32, mean: f32) {
        eprintln!("headless render [{label}] luma: min={min:.3} max={max:.3} mean={mean:.3}");
        // Bright sky pixels present (catches all-black / DDA-returns-nothing).
        assert!(max > 0.55, "[{label}] no bright sky pixels (max luma {max:.3}) â€” render likely broken");
        // Dark terrain pixels present (catches all-sky / DDA never hits geometry).
        assert!(min < 0.45, "[{label}] no dark terrain pixels (min luma {min:.3}) â€” DDA not hitting voxels");
        assert!(mean > 0.05 && mean < 0.95, "[{label}] implausible mean luma {mean:.3}");
    }

    /// Densest water / leaf 32x32-column cells of a filled world (columns
    /// sampled at stride 4), plus the ground height under the leaf cell â€”
    /// deterministic camera anchors shared by the water/foliage content test
    /// and the timing benchmark.
    fn find_scene_anchors(world: &World) -> (glam::IVec2, glam::IVec2, i32) {
        use crate::voxel::{is_water_mat, is_leaf_mat, m_to_vox_i};
        // The scan is in METRES: an 8 m cell sampled every metre, over the whole
        // window, looking for water at the surface and leaves between 5 m and
        // 35 m up. Written in voxels (a 32-voxel cell every 4 voxels, y 1..200)
        // it silently became a 3.2 m cell at 10 cm - eight times the cells, each
        // too small to hold a lake, and a y window that stopped below the trees.
        let cell = m_to_vox_i(8.0);
        let step = m_to_vox_i(1.0).max(1);
        let cells_x = crate::voxel::WORLD_VOXELS_X as i32 / cell;
        let cells_z = crate::voxel::WORLD_VOXELS_Z as i32 / cell;
        let y_top = m_to_vox_i(50.0).min(crate::voxel::WORLD_VOXELS_Y as i32 - 1);
        let (leaf_lo, leaf_hi) = (m_to_vox_i(5.0), m_to_vox_i(35.0).min(y_top));
        let mut best_water = (0usize, glam::IVec2::ZERO);
        let mut best_leaf = (0usize, glam::IVec2::ZERO);
        for cz in 0..cells_z {
            for cx in 0..cells_x {
                let (mut water_n, mut leaf_n) = (0usize, 0usize);
                for dz in (0..cell).step_by(step as usize) {
                    for dx in (0..cell).step_by(step as usize) {
                        let (x, z) = (cx * cell + dx, cz * cell + dz);
                        for y in (1..y_top).rev() {
                            let m = world.material_at_world(x, y, z);
                            if m == MAT_AIR { continue; }
                            if is_water_mat(m) { water_n += 1; }
                            break;
                        }
                        for y in (leaf_lo..leaf_hi).step_by(step as usize) {
                            if is_leaf_mat(world.material_at_world(x, y, z)) { leaf_n += 1; }
                        }
                    }
                }
                let c = glam::IVec2::new(cx * cell + cell / 2, cz * cell + cell / 2);
                if water_n > best_water.0 { best_water = (water_n, c); }
                if leaf_n > best_leaf.0 { best_leaf = (leaf_n, c); }
            }
        }
        let leaf_ground = (1..y_top)
            .rev()
            .find(|&y| world.material_at_world(best_leaf.1.x, y, best_leaf.1.y) != MAT_AIR)
            .unwrap_or(m_to_vox_i(20.0));
        eprintln!(
            "scenario anchors: water cell {:?} ({} cols), leaf cell {:?} ({} voxels, ground y={})",
            best_water.1, best_water.0, best_leaf.1, best_leaf.0, leaf_ground
        );
        (best_water.1, best_leaf.1, leaf_ground)
    }

    fn clamp_anchor(v: i32) -> f32 {
        // Keep a 12 m margin off the window edge so a camera placed at an anchor
        // still has world in front of it. WAS 48..464 of 512, i.e. the same 12 m
        // written as voxels.
        let m = crate::voxel::m_to_vox_i(12.0);
        v.max(m).min(crate::voxel::WORLD_VOXELS_X as i32 - m) as f32
    }

    /// Densest 32x32 column-cell in one specific material, for per-species
    /// views. None when the demo seed grew no such trees in the slot window
    /// (callers skip loudly instead of asserting on an absent species).
    fn find_species_anchor(world: &World, mat: u8) -> Option<(glam::IVec2, i32)> {
        let cells = crate::voxel::WORLD_VOXELS_X as i32 / crate::voxel::m_to_vox_i(8.0);
        let mut best = (0usize, glam::IVec2::ZERO);
        for cz in 0..cells {
            for cx in 0..cells {
                let mut n = 0usize;
                for dz in (0..32).step_by(4) {
                    for dx in (0..32).step_by(4) {
                        let (x, z) = (cx * 32 + dx, cz * 32 + dz);
                        for y in 60..140 {
                            if world.material_at_world(x, y, z) == mat { n += 1; }
                        }
                    }
                }
                let c = glam::IVec2::new(cx * 32 + 16, cz * 32 + 16);
                if n > best.0 { best = (n, c); }
            }
        }
        if best.0 == 0 { return None; }
        let ground = (1..200)
            .rev()
            .find(|&y| world.material_at_world(best.1.x, y, best.1.y) != MAT_AIR)
            .unwrap_or(80);
        Some((best.1, ground))
    }

    /// Fraction of pixels in the bottom 60% of the frame matching a colour
    /// class. The top rows are excluded so sky can't satisfy a "blue water"
    /// check.
    fn ground_fraction(rgba: &[u8], w: usize, h: usize, class: fn(f32, f32, f32) -> bool) -> f32 {
        let y0 = h * 2 / 5;
        let mut n = 0usize;
        let mut hits = 0usize;
        for y in y0..h {
            for x in 0..w {
                let i = (y * w + x) * 4;
                let r = rgba[i] as f32 / 255.0;
                let g = rgba[i + 1] as f32 / 255.0;
                let b = rgba[i + 2] as f32 / 255.0;
                n += 1;
                if class(r, g, b) { hits += 1; }
            }
        }
        hits as f32 / n.max(1) as f32
    }

    /// Injected falling leaves must respect world depth: one leaf in the
    /// open is visible, one under a stone slab and one under a water surface
    /// are not (water pixels export their SURFACE t). Pure-red tint makes
    /// the classification unambiguous; the count band asserts exactly one
    /// leaf's worth of pixels regardless of screen orientation.
    #[test]
    fn leaf_occlusion_render() {
        use crate::leaffall::LeafInstance;
        use crate::voxel::{MAT_STONE, MAT_WATER};
        let mut world = World::new();
        for z in 216..264u32 {
            for x in 216..264u32 {
                world.set_voxel(x, 60, z, MAT_STONE);
            }
        }
        // Station B: stone slab; station C: floating water pool. Station A
        // (x=228) is open ground.
        for z in 236..244u32 {
            for x in 236..244u32 {
                world.set_voxel(x, 66, z, MAT_STONE);
            }
            for x in 248..256u32 {
                world.set_voxel(x, 66, z, MAT_WATER);
            }
        }
        let leaf = |x: f32| LeafInstance {
            pos: [x, 63.0, 240.0],
            size: 1.2,
            rot: 0.3,
            tilt_phase: 0.0,
            sprite: crate::sprites::SPR_LEAF_OAK as u32,
            tint: 0xff00_00ff, // pure red
        };
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(242.0, 85.0, 240.0);
        cam.yaw = 0.0;
        cam.pitch = -1.55; // straight down
        let (w, h) = (640usize, 400usize);
        sync_voxlight_shells(&mut world);
        let Some(frame) = render_rgba_ext(
            &world, &cam, w as u32, h as u32,
            &[leaf(228.0), leaf(240.0), leaf(252.0)],
        ) else {
            eprintln!("no GPU adapter â€” skipping leaf occlusion test");
            return;
        };
        let mut red = 0usize;
        for px in frame.chunks_exact(4) {
            let (r, g, b) = (px[0] as f32, px[1] as f32, px[2] as f32);
            if r > 90.0 && r > g * 2.0 && r > b * 2.0 {
                red += 1;
            }
        }
        eprintln!("leaf occlusion: red pixels {red}");
        // Measured: one visible leaf = 349 red px; all three (broken depth
        // test) would be ~1050. The band discriminates both failure modes.
        assert!(red > 100, "the open-air leaf is not visible ({red} red px)");
        assert!(
            red < 700,
            "occluded leaves are showing - depth test broken ({red} red px)"
        );
    }

    /// Two-phase render reproducing the temporal-differential staleness the
    /// windowed app has: frame A at t0 with ALL tiles dirty, frame B at t1
    /// with only a checkerboard of 8x8 screen tiles dirty - the clean tiles
    /// keep frame A's pixels, exactly like the rotating anim-refresh leaves
    /// most tiles stale each frame. Returns frame B. Any per-frame-varying
    /// term baked inside the tile-gated pass shows up as tile-aligned seams.
    /// Read an rgba16float texture back and fold to rgba8-shaped bytes so
    /// luma math written for 4-byte texels keeps working on HDR sources.
    fn read_hdr_as_rgba8(
        device: &wgpu::Device, queue: &wgpu::Queue, tex: &wgpu::Texture, w: u32, h: u32,
    ) -> Vec<u8> {
        let half_to_u8 = |bits: u16| -> u8 {
            let exp = ((bits >> 10) & 0x1F) as i32;
            let man = (bits & 0x3FF) as f32;
            let mag = if exp == 0 {
                man / 1024.0 * (-14f32).exp2()
            } else {
                (1.0 + man / 1024.0) * ((exp - 15) as f32).exp2()
            };
            let v = if bits & 0x8000 != 0 { -mag } else { mag };
            (v.clamp(0.0, 1.0) * 255.0).round() as u8
        };
        let bpr = w * 8;
        let readback = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("hdr readback"),
            size: (bpr * h) as u64,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });
        let mut e = device.create_command_encoder(&Default::default());
        e.copy_texture_to_buffer(
            wgpu::TexelCopyTextureInfo {
                texture: tex, mip_level: 0, origin: wgpu::Origin3d::ZERO,
                aspect: wgpu::TextureAspect::All,
            },
            wgpu::TexelCopyBufferInfo {
                buffer: &readback,
                layout: wgpu::TexelCopyBufferLayout {
                    offset: 0, bytes_per_row: Some(bpr), rows_per_image: Some(h),
                },
            },
            wgpu::Extent3d { width: w, height: h, depth_or_array_layers: 1 },
        );
        queue.submit(std::iter::once(e.finish()));
        let slice = readback.slice(..);
        slice.map_async(wgpu::MapMode::Read, |_| {});
        device.poll(wgpu::PollType::wait_indefinitely()).unwrap();
        let raw = slice.get_mapped_range().unwrap().to_vec();
        let mut out = vec![0u8; (w * h * 4) as usize];
        for i in 0..(w * h) as usize {
            for c in 0..4 {
                let bits = u16::from_le_bytes([raw[i * 8 + c * 2], raw[i * 8 + c * 2 + 1]]);
                out[i * 4 + c] = half_to_u8(bits);
            }
        }
        out
    }

    fn render_checkerboard_probe(
        world: &World, cam: &Camera, w: u32, h: u32, t0: f32, t1: f32,
    ) -> Option<Vec<u8>> {
        let (device, queue, _gpu) = headless_device()?;
        let wo = world.world_origin_voxel();
        let cu0 = CameraUniform::from_camera(cam, w, h, t0, t0, wo, [0.0, 0.0], 0.0);
        let camera_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("camera"),
            contents: bytemuck::bytes_of(&cu0),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let bricks_buf = storage(&device, "bricks", bytemuck::cast_slice(&world.bricks));
        let tile_mask_buf = storage(&device, "tile_mask", bytemuck::cast_slice(&world.tile_mask));
        let chunk_mask_buf = storage(&device, "chunk_mask", bytemuck::cast_slice(&world.chunk_mask));
        let l4_mask_buf = storage(&device, "l4_mask", bytemuck::cast_slice(&world.l4_mask));
        let brick_uniform_buf = storage(&device, "bu", bytemuck::cast_slice(&pack_u8_to_u32(&world.brick_uniform)));
        let tile_uniform_buf = storage(&device, "tu", bytemuck::cast_slice(&pack_u8_to_u32(&world.tile_uniform)));
        let palette = default_palette();
        let palette_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("palette"),
            contents: bytemuck::cast_slice(&palette),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let tiles_w = (w + 7) / 8;
        let tiles_h = (h + 7) / 8;
        let words = ((tiles_w * tiles_h) as usize + 31) / 32;
        let td = storage(&device, "td", bytemuck::cast_slice(&vec![u32::MAX; words]));
        let players = storage(&device, "pl", &vec![0u8; 16 + MAX_REMOTE_PLAYERS * 16]);
        let (_o, ov) = create_hdr_texture(&device, w, h);
        let (_b, bv) = create_beam_texture(&device, w, h);
        let (_c, csv, _csw) = create_cloud_texture(&device, w, h);
        let csamp = device.create_sampler(&wgpu::SamplerDescriptor {
            mag_filter: wgpu::FilterMode::Linear,
            min_filter: wgpu::FilterMode::Linear,
            ..Default::default()
        });
        let (_lo, lov) = create_lighting_texture(&device, w, h);
        let tpb = create_transp_buf(&device, w, h);
        let spr = storage(&device, "sprites", bytemuck::cast_slice(&crate::sprites::encoded()));
        let (_dt, dv) = create_depth_texture(&device, w, h);
        let (_gt, gv) = create_hdr_texture(&device, w, h);
        let (_dd, ddv) = create_depth_texture(&device, 1, 1);
        let bgl = create_compute_bgl(&device);
        let vl_bufs = VoxLightBuffers::new(&device);
        let bg = make_compute_bg(
            &device, &bgl, &camera_buf, &bricks_buf, &tile_mask_buf, &chunk_mask_buf,
            &palette_buf, &gv, &bv, &td, &players, &brick_uniform_buf, &tile_uniform_buf,
            &l4_mask_buf, &csv, &csamp, &lov, &tpb, &spr, &dv, &ov, &bv, &vl_bufs,
        );
        let bg_compose = make_compute_bg(
            &device, &bgl, &camera_buf, &bricks_buf, &tile_mask_buf, &chunk_mask_buf,
            &palette_buf, &ov, &bv, &td, &players, &brick_uniform_buf, &tile_uniform_buf,
            &l4_mask_buf, &csv, &csamp, &lov, &tpb, &spr, &ddv, &gv, &dv, &vl_bufs,
        );
        let pll = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: None, bind_group_layouts: &[Some(&bgl)], immediate_size: 0,
        });
        let m = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: None, source: wgpu::ShaderSource::Wgsl(raymarch_source().into()),
        });
        let mk = |entry: &str| device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: None, layout: Some(&pll), module: &m, entry_point: Some(entry),
            compilation_options: Default::default(), cache: None,
        });
        let p_main = mk("cs_main");
        let p_transp = mk("cs_transparent");
        let p_compose = mk("cs_compose");
        let cloud_bgl = create_cloud_bgl(&device);
        let cloud_pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: None, bind_group_layouts: &[Some(&cloud_bgl)], immediate_size: 0,
        });
        let p_clouds_full = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: None, layout: Some(&cloud_pl), module: &m, entry_point: Some("cs_clouds"),
            compilation_options: Default::default(), cache: None,
        });
        let cloud_bg = make_cloud_bg(&device, &cloud_bgl, &camera_buf, &_csw);
        let frame = |dev: &wgpu::Device, q: &wgpu::Queue| {
            let mut e = dev.create_command_encoder(&Default::default());
            {
                let mut cp = e.begin_compute_pass(&Default::default());
                cp.set_pipeline(&p_clouds_full);
                cp.set_bind_group(0, &cloud_bg, &[]);
                cp.dispatch_workgroups(((w + 1) / 2 + 7) / 8, ((h + 1) / 2 + 7) / 8, 1);
            }
            {
                let mut cp = e.begin_compute_pass(&Default::default());
                cp.set_pipeline(&p_main);
                cp.set_bind_group(0, &bg, &[]);
                cp.dispatch_workgroups((w + 7) / 8, (h + 7) / 8, 1);
            }
            {
                let mut cp = e.begin_compute_pass(&Default::default());
                cp.set_pipeline(&p_transp);
                cp.set_bind_group(0, &bg, &[]);
                cp.dispatch_workgroups((w + 7) / 8, (h + 7) / 8, 1);
            }
            {
                let mut cp = e.begin_compute_pass(&Default::default());
                cp.set_pipeline(&p_compose);
                cp.set_bind_group(0, &bg_compose, &[]);
                cp.dispatch_workgroups((w + 7) / 8, (h + 7) / 8, 1);
            }
            q.submit(std::iter::once(e.finish()));
        };
        // Frame A: everything dirty at t0.
        frame(&device, &queue);
        // Frame B: t1, checkerboard tile mask (alternate 8x8 tiles stale).
        let mut mask = vec![0u32; words];
        for ty in 0..tiles_h {
            for tx in 0..tiles_w {
                if (tx + ty) % 2 == 0 {
                    let idx = (ty * tiles_w + tx) as usize;
                    mask[idx >> 5] |= 1u32 << (idx & 31);
                }
            }
        }
        queue.write_buffer(&td, 0, bytemuck::cast_slice(&mask));
        let cu1 = CameraUniform::from_camera(cam, w, h, t1, t1, wo, [0.0, 0.0], 0.0);
        queue.write_buffer(&camera_buf, 0, bytemuck::bytes_of(&cu1));
        frame(&device, &queue);
        // Read back frame B.
        Some(read_hdr_as_rgba8(&device, &queue, &_o, w, h))
    }

    /// The cloud-shadow checkerboard, measured: with half the tiles one
    /// frame stale (as in real play), the luma difference across 8x8 tile
    /// BOUNDARIES must not exceed the difference at tile interiors by more
    /// than sensor noise. Any per-frame-varying term (god-ray jitter, cloud
    /// composite) baked inside the tile-gated pass fails this.
    #[test]
    fn no_tile_checkerboard_in_god_rays() {
        use crate::voxel::MAT_STONE;
        // Stone floor on purpose: grass tops have time-animated sway that
        // the rotating anim-refresh legitimately lags by a few frames -
        // this test isolates the per-frame-RANDOM terms (god-ray jitter,
        // cloud composite) whose tile staleness is the standing
        // checkerboard.
        let mut world = World::new();
        for z in 60..200u32 {
            for x in 60..200u32 {
                for y in 58..63u32 {
                    world.set_voxel(x, y, z, MAT_STONE);
                }
            }
        }
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(150.0, 66.0, 130.0);
        cam.yaw = -std::f32::consts::FRAC_PI_2; // toward -x, into the low sun
        cam.pitch = -0.06;
        let (w, h) = (640usize, 400usize);
        // t ~ 77.6: sun_dir_at angle ~ pi -> sun low on the -x horizon; god
        // rays active over the whole ground view.
        let Some(frame) = render_checkerboard_probe(&world, &cam, w as u32, h as u32, 77.4, 77.4 + 1.0 / 60.0)
        else {
            eprintln!("no GPU adapter â€” skipping checkerboard probe");
            return;
        };
        let luma = |x: usize, y: usize| -> f32 {
            let i = (y * w + x) * 4;
            (frame[i] as f32 + frame[i + 1] as f32 + frame[i + 2] as f32) / (3.0 * 255.0)
        };
        // Ground region only (lower third - the horizon band would leak
        // tile-gated sky/sun-disc gradients into the metric).
        let (y0, y1) = (h * 2 / 3, h - 8);
        let mut b_sum = 0.0f64;
        let mut b_n = 0u32;
        let mut i_sum = 0.0f64;
        let mut i_n = 0u32;
        for y in y0..y1 {
            for x in 8..w - 9 {
                let d = (luma(x, y) - luma(x + 1, y)).abs() as f64;
                if x % 8 == 7 {
                    b_sum += d;
                    b_n += 1;
                } else if x % 8 == 3 {
                    i_sum += d;
                    i_n += 1;
                }
            }
        }
        for y in (y0..y1 - 1).step_by(1) {
            for x in 8..w - 8 {
                let d = (luma(x, y) - luma(x, y + 1)).abs() as f64;
                if y % 8 == 7 {
                    b_sum += d;
                    b_n += 1;
                } else if y % 8 == 3 {
                    i_sum += d;
                    i_n += 1;
                }
            }
        }
        let boundary = b_sum / b_n.max(1) as f64;
        let interior = i_sum / i_n.max(1) as f64;
        let excess = boundary - interior;
        eprintln!("checkerboard probe: boundary {boundary:.5} interior {interior:.5} excess {excess:.5}");
        assert!(
            excess < 0.0025,
            "tile-aligned seams: boundary luma delta exceeds interior by {excess:.5}"
        );
    }

