    /// Guard for the "shadows flying over the ground" artifact class: on
    /// RIGID geometry (bare grass-top plain, nothing that can move) the
    /// image must be temporally STILL when only animation time advances
    /// (sun frozen via the time/sun split, so shadow edges and god rays are
    /// bit-stable). Two frames 2 s apart are diffed in luma and averaged
    /// over 16x16 blocks; the spatial std-dev of block means over the
    /// plain-only crop must sit at the noise floor - any patch-scale
    /// brightness field traveling across rigid ground (the old
    /// `base *= 1.0 + sway` modulation and its normal-flutter cousins) is
    /// the bug. The canopy band is reported unguarded: leaves really move
    /// (card gust shear is geometry, not a shading field).
    /// Measured (sun frozen): pre-fix plain crop 0.0066, post-fix 0.0017
    /// (the residual is the per-frame god-ray jitter noise floor); canopy
    /// band 0.0052 -> 0.0031. Threshold 0.004 sits between.
    #[test]
    fn no_field_scale_luma_waves() {
        let mut world = build_leaf_lab_world();
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(118.0, 79.0, 82.0);
        cam.yaw = 0.0;
        cam.pitch = -0.5;
        let (w, h) = (960usize, 540usize);
        sync_voxlight_shells(&mut world);
        let Some(a) = render_rgba_full_opts(&world, &cam, w as u32, h as u32, &[], 30.0, 30.0, false, false) else {
            eprintln!("no GPU adapter â€” skipping luma-wave probe");
            return;
        };
        let b = render_rgba_full_opts(&world, &cam, w as u32, h as u32, &[], 32.0, 30.0, false, false).unwrap();
        let luma = |f: &[u8], x: usize, y: usize| {
            let i = (y * w + x) * 4;
            (f[i] as f32 + f[i + 1] as f32 + f[i + 2] as f32) / (3.0 * 255.0)
        };
        let (bw, bh) = (w / 16, h / 16);
        let block_std = |rows: std::ops::Range<usize>| {
            let mut means = Vec::new();
            for by in rows {
                for bx in 0..bw {
                    let mut sum = 0.0f32;
                    for y in by * 16..by * 16 + 16 {
                        for x in bx * 16..bx * 16 + 16 {
                            sum += luma(&b, x, y) - luma(&a, x, y);
                        }
                    }
                    means.push(sum / 256.0);
                }
            }
            let n = means.len() as f32;
            let global = means.iter().sum::<f32>() / n;
            (means.iter().map(|m| (m - global) * (m - global)).sum::<f32>() / n).sqrt()
        };
        // Bottom 30% of the frame: nearby bare plain in front of the tree
        // row - rigid ground only. Upper band contains the canopies.
        let plain = block_std(bh * 7 / 10..bh);
        let canopy = block_std(0..bh * 7 / 10);
        eprintln!("luma-wave spatial std: plain {plain:.4}, canopy band {canopy:.4}");
        assert!(
            plain < 0.004,
            "traveling luma waves on rigid ground (plain spatial std {plain:.4} >= 0.004): \
             a patch-scale brightness field is moving across geometry that cannot move"
        );
    }

    /// Sky lookdev: camera on open ground looking up at the cloud band at
    /// three day phases. Prints the cloud / clear-sky split of the upper
    /// half so cumulus tuning has a number next to the eyeball judgement
    /// (target: distinct clumps with real clear sky between, not a veil).
    #[test]
    #[ignore]
    fn dump_sky_views() {
        let mut world = World::new();
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(256.0, 70.0, 256.0);
        cam.yaw = 0.0;
        cam.pitch = 0.55;
        std::fs::create_dir_all("target/lookdev").unwrap();
        let views = [("sky_t20", 20.0f32, 0.55), ("sky_t30", 30.0, 0.55), ("sky_t44", 44.0, 0.55), ("sky_zenith_t30", 30.0, 1.25)];
        sync_voxlight_shells(&mut world);
        for (name, t, pitch) in views {
            cam.pitch = pitch;
            let Some(rgba) = render_rgba_at_time(&world, &cam, 960, 540, t) else {
                eprintln!("no GPU â€” skipping");
                return;
            };
            let (w, h) = (960usize, 540usize);
            let mut cloud = 0usize;
            let mut total = 0usize;
            for y in 0..h / 2 {
                for x in 0..w {
                    let i = (y * w + x) * 4;
                    let (r, g, b) = (rgba[i] as f32, rgba[i + 1] as f32, rgba[i + 2] as f32);
                    // Cloud = desaturated (blue not dominant); sky = blue-led.
                    if b < g + 18.0 && r > 60.0 {
                        cloud += 1;
                    }
                    total += 1;
                }
            }
            eprintln!("{name}: cloud fraction {:.3}", cloud as f32 / total as f32);
            let path = format!("target/lookdev/{name}.png");
            let file = std::fs::File::create(&path).unwrap();
            let mut enc = png::Encoder::new(std::io::BufWriter::new(file), 960, 540);
            enc.set_color(png::ColorType::Rgba);
            enc.set_depth(png::BitDepth::Eight);
            enc.write_header().unwrap().write_image_data(&rgba).unwrap();
            eprintln!("wrote {path}");
        }
    }

    /// Cloud-shadow feature guard: over a flat plain with the sun frozen,
    /// patch-scale ground shade must DRIFT when only cloud time advances -
    /// the one signal that separates real cloud shadows from static ground
    /// texture (which cancels in the frame diff) and from god-ray jitter
    /// (which block-averaging removes). The single-frame spatial std is
    /// printed but NOT asserted: the grass texture's own patchiness makes
    /// it non-discriminating (measured 0.027 with no shadow system at
    /// all). Fail-first drift: 0.0000 without the system; with it: see the
    /// measured value in the assert margin.
    #[test]
    fn cloud_shadows_present_and_drifting() {
        use crate::voxel::MAT_GRASS;
        let mut world = World::new();
        for z in 156..356u32 {
            for x in 156..356u32 {
                world.set_voxel(x, 60, z, MAT_GRASS);
            }
        }
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(256.0, 140.0, 256.0);
        cam.yaw = 0.0;
        cam.pitch = -1.5;
        let (w, h) = (960usize, 540usize);
        sync_voxlight_shells(&mut world);
        let Some(a) = render_rgba_time_sun(&world, &cam, w as u32, h as u32, 30.0, 30.0) else {
            eprintln!("no GPU adapter â€” skipping cloud shadow test");
            return;
        };
        // Cloud drift rides the DAY clock (camera.sun_time - so freeze-time
        // freezes clouds with the sun, and the rigid-ground guard can isolate
        // rogue fields). Advancing both clocks together is exactly normal
        // gameplay time; the patch-scale cloud-shade motion dominates the
        // spatial std over the mild 3-degree sun shift.
        let b = render_rgba_time_sun(&world, &cam, w as u32, h as u32, 32.0, 32.0).unwrap();
        let luma = |f: &[u8], x: usize, y: usize| {
            let i = (y * w + x) * 4;
            (f[i] as f32 + f[i + 1] as f32 + f[i + 2] as f32) / (3.0 * 255.0)
        };
        let (bw, bh) = (w / 16, h / 16);
        let spatial_std = |f: &dyn Fn(usize, usize) -> f32| {
            let mut means = Vec::with_capacity(bw * bh);
            for by in 0..bh {
                for bx in 0..bw {
                    let mut sum = 0.0f32;
                    for y in by * 16..by * 16 + 16 {
                        for x in bx * 16..bx * 16 + 16 {
                            sum += f(x, y);
                        }
                    }
                    means.push(sum / 256.0);
                }
            }
            let n = means.len() as f32;
            let g = means.iter().sum::<f32>() / n;
            (means.iter().map(|m| (m - g) * (m - g)).sum::<f32>() / n).sqrt()
        };
        let shade = spatial_std(&|x, y| luma(&a, x, y));
        let drift = spatial_std(&|x, y| luma(&b, x, y) - luma(&a, x, y));
        eprintln!("cloud shadow spatial std {shade:.4}, drift std {drift:.4}");
        assert!(
            drift > 0.004,
            "no drifting cloud shade on the ground (drift std {drift:.4} <= 0.004): \
             either shadows are missing or they do not move with the clouds"
        );
    }

    /// Isolated material bench: a stone plain with a 4x4x4 cube of every
    /// textured material in two sunlit rows, for tuning the procedural
    /// block textures against one view.
    fn build_material_lab_world() -> World {
        use crate::voxel::*;
        let mut world = World::new();
        for z in 80..136u32 {
            for x in 88..168u32 {
                for y in 58..62u32 {
                    world.set_voxel(x, y, z, MAT_STONE);
                }
                world.set_voxel(x, 62, z, MAT_GRASS);
            }
        }
        let mats: [u8; 16] = [
            MAT_STONE, MAT_DIRT, MAT_GRASS, MAT_SAND, MAT_SNOW, MAT_WOOD, MAT_WOOD_BIRCH,
            MAT_WOOD_PINE, MAT_ICE, MAT_COAL, MAT_IRON, MAT_GOLD, MAT_DIAMOND, MAT_LAVA,
            MAT_CACTUS, MAT_GLASS,
        ];
        for (i, m) in mats.iter().enumerate() {
            let bx = 92 + (i % 8) as u32 * 9;
            let bz = 104 + (i / 8) as u32 * 12;
            for y in 63..67u32 {
                for dz in 0..4u32 {
                    for dx in 0..4u32 {
                        world.set_voxel(bx + dx, y, bz + dz, *m);
                    }
                }
            }
        }
        world
    }

    /// Shallow pool with a water-LEVEL gradient (L2..L8), the case that
    /// makes each cell's surface patch bulge and crease into "arches" - a
    /// static stand-in for flowing water draining toward the centre.
    /// Water fully roofed by a stone slab a few blocks above - the
    /// reflection off the water must show the dark roof underside, never the
    /// sky. Camera sits under the overhang looking at the pool.
    #[test]
    #[ignore]
    fn dump_overhang_water() {
        use crate::voxel::{MAT_STONE, MAT_WATER};
        let mut world = World::new();
        // Fully SEALED stone box (floor, four walls, roof) - no sky visible
        // anywhere inside. Solid shell over [100,124]^2 x [60,68], hollow
        // interior.
        for y in 60..69u32 {
            for z in 100..125u32 {
                for x in 100..125u32 {
                    let shell = x == 100 || x == 124 || z == 100 || z == 124
                        || y == 60 || y == 68;
                    if shell {
                        world.set_voxel(x, y, z, MAT_STONE);
                    }
                }
            }
        }
        for z in 101..124u32 {
            for x in 101..124u32 {
                world.set_voxel(x, 61, z, MAT_WATER); // 1-deep pool (foam-prone)
            }
        }
        world.rebuild_active_bricks();
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(104.0, 63.0, 104.0);
        cam.yaw = std::f32::consts::FRAC_PI_4;
        cam.pitch = -0.30;
        sync_voxlight_shells(&mut world);
        let Some(rgba) = render_rgba(&world, &cam, 960, 540) else {
            eprintln!("no GPU â€” skipping");
            return;
        };
        std::fs::create_dir_all("target/lookdev").unwrap();
        let file = std::fs::File::create("target/lookdev/overhang_water.png").unwrap();
        let mut enc = png::Encoder::new(std::io::BufWriter::new(file), 960, 540);
        enc.set_color(png::ColorType::Rgba);
        enc.set_depth(png::BitDepth::Eight);
        enc.write_header().unwrap().write_image_data(&rgba).unwrap();
        eprintln!("wrote target/lookdev/overhang_water.png");
    }

    /// A full still lake in a stone basin (all L8), active bricks registered
    /// so the physics sim will run on it.
    fn build_lake_world() -> World {
        use crate::voxel::*;
        let mut world = World::new();
        for z in 106..130u32 {
            for x in 106..130u32 {
                for y in 44..50u32 {
                    world.set_voxel(x, y, z, MAT_STONE);
                }
                let edge = x == 106 || x == 129 || z == 106 || z == 129;
                if edge {
                    for y in 50..70u32 {
                        world.set_voxel(x, y, z, MAT_STONE);
                    }
                }
            }
        }
        // Deep water: y=50..64 (14 layers).
        for z in 107..129u32 {
            for x in 107..129u32 {
                for y in 50..64u32 {
                    world.set_voxel(x, y, z, MAT_WATER);
                }
            }
        }
        world.rebuild_active_bricks();
        world
    }

