    /// Isolated leaf-rendering bench: a flat grass plain with four hand-built
    /// canopies (oak, birch, pine, autumn) at known positions, fringe shells
    /// painted with the same sphere semantics as worldgen paint_canopy
    /// (fringe r+1 first, leaves overwrite, trunk overwrites both). Leaf
    /// rendering changes are tuned and judged HERE, in isolation, before the
    /// full-world views.
    fn build_leaf_lab_world() -> World {
        use crate::voxel::{
            MAT_GRASS, MAT_LEAF_FRINGE, MAT_LEAVES, MAT_LEAVES_AUTUMN, MAT_LEAVES_BIRCH,
            MAT_LEAVES_PINE, MAT_STONE, MAT_WOOD, MAT_WOOD_BIRCH, MAT_WOOD_PINE,
        };
        let mut world = World::new();
        for z in 80..136u32 {
            for x in 88..152u32 {
                for y in 58..62u32 {
                    world.set_voxel(x, y, z, MAT_STONE);
                }
                world.set_voxel(x, 62, z, MAT_GRASS);
            }
        }
        let trees: [(u32, u32, u8, u8); 4] = [
            (100, 100, MAT_WOOD, MAT_LEAVES),
            (112, 100, MAT_WOOD_BIRCH, MAT_LEAVES_BIRCH),
            (124, 100, MAT_WOOD_PINE, MAT_LEAVES_PINE),
            (136, 100, MAT_WOOD, MAT_LEAVES_AUTUMN),
        ];
        for (cx, cz, wood, leaf) in trees {
            let cy = 69i32;
            // Fringe shell r=4 (widened one cell horizontally), then leaves
            // r=3, then trunk - same overwrite order and shell shape as
            // worldgen's paint_canopy/paint_fringe_shell.
            for (r, m, wide) in [(4i32, MAT_LEAF_FRINGE, 1i32), (3, leaf, 0)] {
                for dy in -r..=r {
                    for dx in -(r + wide)..=(r + wide) {
                        for dz in -(r + wide)..=(r + wide) {
                            let hx = (dx.abs() - wide).max(0);
                            let hz = (dz.abs() - wide).max(0);
                            if hx * hx + dy * dy + hz * hz > r * r {
                                continue;
                            }
                            world.set_voxel(
                                (cx as i32 + dx) as u32,
                                (cy + dy) as u32,
                                (cz as i32 + dz) as u32,
                                m,
                            );
                        }
                    }
                }
            }
            for y in 63..=69u32 {
                world.set_voxel(cx, y, cz, wood);
            }
        }
        world
    }

    fn leaf_lab_cams() -> [(&'static str, Camera); 3] {
        // Side view: eye level, ~4.5 units from the oak crown edge, sky
        // behind the silhouette - the discriminating view for whether
        // individual leaves read.
        let mut side = Camera::new();
        side.pos = glam::Vec3::new(100.0, 69.0, 91.5);
        side.yaw = 0.0;
        side.pitch = 0.0;
        let mut top = Camera::new();
        top.pos = glam::Vec3::new(100.0, 78.5, 100.0);
        top.yaw = 0.0;
        top.pitch = -1.5;
        let mut all = Camera::new();
        all.pos = glam::Vec3::new(118.0, 70.0, 83.0);
        all.yaw = 0.0;
        all.pitch = -0.08;
        [("leaf_lab_side", side), ("leaf_lab_top", top), ("leaf_lab_all", all)]
    }

    /// Individual leaves at the crown edge = high local contrast + sky gaps
    /// INSIDE the silhouette. Prints the metrics; the discriminating
    /// thresholds are set from measured pre/post values when the leaf cloud
    /// lands (fail-first proof recorded there).
    #[test]
    fn leaf_lab_reads_individual_leaves() {
        let mut world = build_leaf_lab_world();
        let [(_, side), _, _] = leaf_lab_cams();
        let (w, h) = (640usize, 400usize);
        sync_voxlight_shells(&mut world);
        let Some(frame) = render_rgba(&world, &side, w as u32, h as u32) else {
            eprintln!("no GPU adapter â€” skipping leaf lab test");
            return;
        };
        // Crown-edge crop: upper-left region of the canopy against sky.
        let (x0, y0, cw, ch) = (200usize, 90usize, 96usize, 96usize);
        let mut lumas = Vec::with_capacity(cw * ch);
        let mut sky = 0usize;
        let mut green = 0usize;
        for y in y0..y0 + ch {
            for x in x0..x0 + cw {
                let i = (y * w + x) * 4;
                let (r, g, b) = (
                    frame[i] as f32 / 255.0,
                    frame[i + 1] as f32 / 255.0,
                    frame[i + 2] as f32 / 255.0,
                );
                lumas.push((r + g + b) / 3.0);
                // Sky gap = blue sky OR a bright cloud behind the crown
                // (cloud layouts move whenever the shared noise stack
                // changes; leaves match neither branch).
                if (b > 0.55 && b > g + 0.05) || (r > 0.62 && g > 0.62 && b > 0.62) {
                    sky += 1;
                }
                if g > r && g > b {
                    green += 1;
                }
            }
        }
        let n = lumas.len() as f32;
        let mean = lumas.iter().sum::<f32>() / n;
        let var = lumas.iter().map(|l| (l - mean) * (l - mean)).sum::<f32>() / n;
        let sky_f = sky as f32 / n;
        let green_f = green as f32 / n;
        eprintln!("leaf lab edge crop: luma std {:.4} sky {sky_f:.3} green {green_f:.3}", var.sqrt());
        // Regression guard only: canopy present and neither hollow nor
        // solid-blocked. "Reads as individual leaves" is judged by the
        // leaf_lab_side/top/all lookdev A/B - every aggregate scalar tried
        // (pixel std, 8x8 block-mean std, connected-component census,
        // outside-silhouette annulus) failed to separate speckle texture
        // from leaf-shaped structure, so no threshold pretends to.
        assert!(green_f > 0.15, "crown edge crop missed the canopy (green {green_f:.3})");
        assert!(sky_f > 0.02 && sky_f < 0.60, "crown edge lost its sky gaps ({sky_f:.3})");
    }

    /// A flat water sheet with a tall wall standing in it, so the sun casts a
    /// hard-edged band of shadow ACROSS THE WATER. The one scene that judges
    /// the stylized water's central claim - that it reads as lit or shadowed
    /// rather than as a mirror - because no natural camera in the demo world
    /// has shadowed open water in frame.
    ///
    /// Geometry is sized off the sun the STILL HARNESS uses, which is
    /// `sun_dir_at(0.0)` = (0.345, 0.887, 0.286), NOT the t=30 sun the flicker
    /// and timing rigs run at. A wall 31 voxels above the surface throws its
    /// shadow ~12 voxels in -x and ~10 in -z, so the camera has to sit on the
    /// -x side of it. Getting that backwards is not a subtle failure: the first
    /// version of this scene put the camera at +x, the whole shadow fell behind
    /// the wall where nothing could see it, and the measurement reported a
    /// 2%-of-frame shadow off a wall 32 voxels tall.
    fn build_water_shadow_world(wall: bool) -> (World, Camera) {
        use crate::voxel::{MAT_SAND, MAT_STONE, MAT_WATER};
        let mut world = World::new();
        for z in 92..180u32 {
            for x in 60..156u32 {
                for y in 60..63u32 {
                    world.set_voxel(x, y, z, MAT_STONE);
                }
                world.set_voxel(x, 63, z, MAT_SAND);
                world.set_voxel(x, 64, z, MAT_WATER);
            }
        }
        // The wall, standing IN the sheet and running along z so its shadow
        // edge is a line of constant x. `wall = false` builds the identical
        // sheet with NOTHING there, which is the reference the shadow is
        // measured against.
        //
        // It has to be nothing, not water: filling the footprint with water
        // instead leaves a 31-voxel water COLUMN standing in the reference
        // frame, water occludes shadow rays, and the reference then carries the
        // same shadow as the subject. That is exactly how the first version of
        // this scene measured a 0.2% shadow on a wall 32 voxels tall.
        if wall {
            for z in 96..178u32 {
                for x in 108..111u32 {
                    for y in 64..96u32 {
                        world.set_voxel(x, y, z, MAT_STONE);
                    }
                }
            }
        }
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(100.0, 88.0, 100.0);
        cam.yaw = 0.0; // along +z, so world x runs across the frame
        cam.pitch = -0.7;
        (world, cam)
    }

    /// Two water bodies meeting only at a diagonal corner, one level apart:
    /// the crafted scene for the connected-surface tests and lookdev. Basin
    /// A (y=64, full L8) over a sand floor; basin B (y=65) floats with open
    /// air beneath its bulk, so any gap at the corner shows the warm floor
    /// behind it. The camera looks diagonally straight at the shared corner
    /// (world point 110, 65, 110).
    fn build_water_terrace_world() -> (World, Camera) {
        use crate::voxel::{MAT_SAND, MAT_STONE, MAT_WATER};
        let mut world = World::new();
        for z in 88..136u32 {
            for x in 88..136u32 {
                for y in 60..63u32 {
                    world.set_voxel(x, y, z, MAT_STONE);
                }
                world.set_voxel(x, 63, z, MAT_SAND);
            }
        }
        for z in 96..110u32 {
            for x in 96..110u32 {
                world.set_voxel(x, 64, z, MAT_WATER);
            }
        }
        for z in 110..124u32 {
            for x in 110..124u32 {
                world.set_voxel(x, 64, z, MAT_STONE); // the terrace shelf
                world.set_voxel(x, 65, z, MAT_WATER);
            }
        }
        // Close-up on the corner: the pin's effect is a quarter-voxel wedge,
        // so the discriminating view must be near enough for it to span
        // tens of pixels.
        let mut cam = Camera::new();
        cam.pos = glam::Vec3::new(106.8, 66.8, 106.8);
        cam.yaw = std::f32::consts::FRAC_PI_4;
        cam.pitch = -0.38;
        (world, cam)
    }

